import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from cluster ----
/** A taxon is either a leaf or an internal grouping; only leaves are terminal. */
type TaxonNode = {
  name: string;
  children?: TaxonNode[];
};

/**
 * Indo-European language family, 28 leaves at mixed depth. Celtic and Hellenic sit one
 * level shallower on purpose: d3.cluster pulls their leaves out to the same column as
 * the deepest ones, which is exactly what separates a dendrogram from a tidy tree.
 */
const languageFamily: TaxonNode = {
  name: 'Indo-European',
  children: [
    {
      name: 'Balto-Slavic',
      children: [
        {
          name: 'Baltic',
          children: [{ name: 'Latvian' }, { name: 'Lithuanian' }]
        },
        {
          name: 'Slavic',
          children: [
            { name: 'Bulgarian' },
            { name: 'Czech' },
            { name: 'Polish' },
            { name: 'Russian' },
            { name: 'Ukrainian' }
          ]
        }
      ]
    },
    {
      name: 'Celtic',
      children: [{ name: 'Irish' }, { name: 'Welsh' }]
    },
    {
      name: 'Germanic',
      children: [
        {
          name: 'North Germanic',
          children: [
            { name: 'Danish' },
            { name: 'Icelandic' },
            { name: 'Norwegian' },
            { name: 'Swedish' }
          ]
        },
        {
          name: 'West Germanic',
          children: [{ name: 'Dutch' }, { name: 'English' }, { name: 'German' }]
        }
      ]
    },
    {
      name: 'Hellenic',
      children: [{ name: 'Greek' }]
    },
    {
      name: 'Indo-Iranian',
      children: [
        {
          name: 'Indo-Aryan',
          children: [{ name: 'Bengali' }, { name: 'Hindi' }, { name: 'Punjabi' }]
        },
        {
          name: 'Iranian',
          children: [{ name: 'Kurdish' }, { name: 'Pashto' }, { name: 'Persian' }]
        }
      ]
    },
    {
      name: 'Italic',
      children: [
        {
          name: 'Romance',
          children: [
            { name: 'French' },
            { name: 'Italian' },
            { name: 'Portuguese' },
            { name: 'Romanian' },
            { name: 'Spanish' }
          ]
        }
      ]
    }
  ]
};

/** Root of the taxonomy to cluster: an internal node carries children, a leaf carries none. */
export type Data = { name: string; children?: Data[] };

type Node = d3.HierarchyPointNode<Data>;
type Link = d3.HierarchyPointLink<Data>;

const MARGIN = { top: 18, right: 16, bottom: 18, left: 92 };
/** Breadth allotted to one leaf row. Height follows from this, never from an aspect ratio. */
const ROW_HEIGHT = 17;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels that would overflow. */
const CHAR_WIDTH = 5.6;
const LABEL_GAP = 6;

function pathOf(node: Node): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

export default function Cluster({ data = languageFamily, width }: { data?: Data; width: number }) {
  const innerWidth = Math.max(width - MARGIN.left - MARGIN.right, 0);

  // x is breadth and y is depth: the layout runs top-down, the drawing runs left-to-right.
  const root = useMemo(() => {
    const hierarchy = d3
      .hierarchy(data)
      .sort((a, b) => d3.ascending(a.data.name, b.data.name));
    const columnWidth = innerWidth / (hierarchy.height + 1);
    return d3.cluster<Data>().nodeSize([ROW_HEIGHT, columnWidth])(hierarchy);
  }, [data, innerWidth]);

  const link = useMemo(
    () =>
      d3
        .linkHorizontal<Link, Node>()
        .x((d) => d.y)
        .y((d) => d.x),
    []
  );

  const [x0, x1] = useMemo(() => {
    const extent = d3.extent(root.descendants(), (d) => d.x);
    return [extent[0] ?? 0, extent[1] ?? 0];
  }, [root]);

  const columnWidth = innerWidth / (root.height + 1);
  const height = Math.round(x1 - x0 + MARGIN.top + MARGIN.bottom);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Dendrogram of the Indo-European language family, drawn left to right"
    >
      <g
        transform={`translate(${MARGIN.left},${MARGIN.top - x0})`}
        fontSize={FONT_SIZE}
        strokeLinejoin="round"
      >
        {root.links().map((l) => (
          <path
            key={pathOf(l.target)}
            d={link(l) ?? undefined}
            fill="none"
            stroke="var(--line)"
            strokeWidth={1.5}
          />
        ))}
        {root.descendants().map((d) => {
          const isLeaf = !d.children;
          const room = isLeaf
            ? innerWidth - d.y + MARGIN.right - LABEL_GAP * 2
            : (d.depth === 0 ? MARGIN.left : columnWidth) - LABEL_GAP * 2;
          const fits = d.data.name.length * CHAR_WIDTH < room;

          return (
            <g key={pathOf(d)} transform={`translate(${d.y},${d.x})`}>
              <title>{pathOf(d)}</title>
              <circle r={2.5} fill={isLeaf ? 'var(--accent)' : 'var(--muted)'} />
              {fits && (
                <text
                  dy="0.32em"
                  x={isLeaf ? LABEL_GAP : -LABEL_GAP}
                  textAnchor={isLeaf ? 'start' : 'end'}
                  fill={isLeaf ? 'var(--text)' : 'var(--muted)'}
                  stroke="var(--bg)"
                  strokeWidth={3}
                  paintOrder="stroke"
                >
                  {d.data.name}
                </text>
              )}
            </g>
          );
        })}
      </g>
    </svg>
  );
}
